   169→// ReadSession reads a session from Claude's storage (JSONL transcript file).
   170→// The session data is stored in NativeData as raw JSONL bytes.
   171→// ModifiedFiles is computed by parsing the transcript.
   172→func (c *ClaudeCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
   173→	if input.SessionRef == "" {
   174→		return nil, errors.New("session reference (transcript path) is required")
   175→	}
   176→
   177→	// Read the raw JSONL file
   178→	data, err := os.ReadFile(input.SessionRef)
   179→	if err != nil {
   180→		return nil, fmt.Errorf("failed to read transcript: %w", err)
   181→	}
   182→
   183→	// Parse to extract computed fields
   184→	lines, err := ParseTranscript(data)
   185→	if err != nil {
   186→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
   187→	}
   188→
   189→	return &agent.AgentSession{
   190→		SessionID:     input.SessionID,
   191→		AgentName:     c.Name(),
   192→		SessionRef:    input.SessionRef,
   193→		StartTime:     time.Now(),
   194→		NativeData:    data,
   195→		ModifiedFiles: ExtractModifiedFiles(lines),
   196→	}, nil
   197→}
