   199→// WriteSession writes a session to Claude's storage (JSONL transcript file).
   200→// Uses the NativeData field which contains raw JSONL bytes.
   201→// The session must have been created by Claude Code (AgentName check).
   202→func (c *ClaudeCodeAgent) WriteSession(session *agent.AgentSession) error {
   203→	if session == nil {
   204→		return errors.New("session is nil")
   205→	}
   206→
   207→	// Verify this session belongs to Claude Code
   208→	if session.AgentName != "" && session.AgentName != c.Name() {
   209→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
   210→	}
   211→
   212→	if session.SessionRef == "" {
   213→		return errors.New("session reference (transcript path) is required")
   214→	}
   215→
   216→	if len(session.NativeData) == 0 {
   217→		return errors.New("session has no native data to write")
   218→	}
   219→
   220→	// Write the raw JSONL data
   221→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
   222→		return fmt.Errorf("failed to write transcript: %w", err)
   223→	}
   224→
   225→	return nil
   226→}
