   417→// TranscriptChunker interface implementation
   418→
   419→// ChunkTranscript splits a JSONL transcript at line boundaries.
   420→// Claude Code uses JSONL format (one JSON object per line), so chunking
   421→// is done at newline boundaries to preserve message integrity.
   422→func (c *ClaudeCodeAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
   423→	chunks, err := agent.ChunkJSONL(content, maxSize)
   424→	if err != nil {
   425→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
   426→	}
   427→	return chunks, nil
   428→}
   429→
   430→// ReassembleTranscript concatenates JSONL chunks with newlines.
   431→//
   432→//nolint:unparam // error return is required by interface, kept for consistency
   433→func (c *ClaudeCodeAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
   434→	return agent.ReassembleJSONL(chunks), nil
   435→}
