   259→// TranscriptAnalyzer interface implementation
   260→
   261→// GetTranscriptPosition returns the current message count of a Gemini transcript.
   262→// Gemini uses JSON format with a messages array, so position is the message count.
   263→// Returns 0 if the file doesn't exist or is empty.
   264→func (g *GeminiCLIAgent) GetTranscriptPosition(path string) (int, error) {
   265→	if path == "" {
   266→		return 0, nil
   267→	}
   268→
   269→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
   270→	if err != nil {
   271→		if os.IsNotExist(err) {
   272→			return 0, nil
   273→		}
   274→		return 0, fmt.Errorf("failed to read transcript: %w", err)
   275→	}
   276→
   277→	if len(data) == 0 {
   278→		return 0, nil
   279→	}
   280→
   281→	transcript, err := ParseTranscript(data)
   282→	if err != nil {
   283→		return 0, fmt.Errorf("failed to parse transcript: %w", err)
   284→	}
   285→
   286→	return len(transcript.Messages), nil
   287→}
