    28→// WriteCommitted writes a committed checkpoint to the entire/sessions branch.
    29→// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
    30→//
    31→// For task checkpoints (IsTask=true), additional files are written under tasks/<tool-use-id>/:
    32→//   - For incremental checkpoints: checkpoints/NNN-<tool-use-id>.json
    33→//   - For final checkpoints: checkpoint.json and agent-<agent-id>.jsonl
    34→func (s *GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
    35→	_ = ctx // Reserved for future use
    36→
    37→	// Validate identifiers to prevent path traversal and malformed data
    38→	if opts.CheckpointID.IsEmpty() {
    39→		return errors.New("invalid checkpoint options: checkpoint ID is required")
    40→	}
    41→	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
    42→		return fmt.Errorf("invalid checkpoint options: %w", err)
    43→	}
    44→	if err := paths.ValidateToolUseID(opts.ToolUseID); err != nil {
    45→		return fmt.Errorf("invalid checkpoint options: %w", err)
    46→	}
    47→	if err := paths.ValidateAgentID(opts.AgentID); err != nil {
    48→		return fmt.Errorf("invalid checkpoint options: %w", err)
    49→	}
    50→
    51→	// Ensure sessions branch exists
    52→	if err := s.ensureSessionsBranch(); err != nil {
    53→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
    54→	}
    55→
    56→	// Get current branch tip and flatten tree
    57→	ref, entries, err := s.getSessionsBranchEntries()
    58→	if err != nil {
    59→		return err
    60→	}
    61→
    62→	// Use sharded path: <id[:2]>/<id[2:]>/
    63→	basePath := opts.CheckpointID.Path() + "/"
    64→
    65→	// Track task metadata path for commit trailer
    66→	var taskMetadataPath string
    67→
    68→	// Handle task checkpoints
    69→	if opts.IsTask && opts.ToolUseID != "" {
    70→		taskMetadataPath, err = s.writeTaskCheckpointEntries(opts, basePath, entries)
    71→		if err != nil {
    72→			return err
    73→		}
    74→	}
    75→
    76→	// Write standard checkpoint entries (transcript, prompts, context, metadata)
    77→	if err := s.writeStandardCheckpointEntries(opts, basePath, entries); err != nil {
    78→		return err
    79→	}
    80→
    81→	// Build and commit
    82→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
    83→	if err != nil {
    84→		return err
    85→	}
    86→
    87→	commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
    88→	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, opts.AuthorName, opts.AuthorEmail)
    89→	if err != nil {
    90→		return err
    91→	}
    92→
    93→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
    94→	newRef := plumbing.NewHashReference(refName, newCommitHash)
    95→	if err := s.repo.Storer.SetReference(newRef); err != nil {
    96→		return fmt.Errorf("failed to set branch reference: %w", err)
    97→	}
    98→
    99→	return nil
   100→}
