   102→// getSessionsBranchEntries returns the sessions branch reference and flattened tree entries.
   103→func (s *GitStore) getSessionsBranchEntries() (*plumbing.Reference, map[string]object.TreeEntry, error) {
   104→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   105→	ref, err := s.repo.Reference(refName, true)
   106→	if err != nil {
   107→		return nil, nil, fmt.Errorf("failed to get sessions branch reference: %w", err)
   108→	}
   109→
   110→	parentCommit, err := s.repo.CommitObject(ref.Hash())
   111→	if err != nil {
   112→		return nil, nil, fmt.Errorf("failed to get commit object: %w", err)
   113→	}
   114→
   115→	baseTree, err := parentCommit.Tree()
   116→	if err != nil {
   117→		return nil, nil, fmt.Errorf("failed to get commit tree: %w", err)
   118→	}
   119→
   120→	entries := make(map[string]object.TreeEntry)
   121→	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
   122→		return nil, nil, err
   123→	}
   124→
   125→	return ref, entries, nil
   126→}
