   128→// writeTaskCheckpointEntries writes task-specific checkpoint entries and returns the task metadata path.
   129→func (s *GitStore) writeTaskCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (string, error) {
   130→	taskPath := basePath + "tasks/" + opts.ToolUseID + "/"
   131→
   132→	if opts.IsIncremental {
   133→		return s.writeIncrementalTaskCheckpoint(opts, taskPath, entries)
   134→	}
   135→	return s.writeFinalTaskCheckpoint(opts, taskPath, entries)
   136→}
