   138→// writeIncrementalTaskCheckpoint writes an incremental checkpoint file during task execution.
   139→func (s *GitStore) writeIncrementalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
   140→	checkpoint := incrementalCheckpointData{
   141→		Type:      opts.IncrementalType,
   142→		ToolUseID: opts.ToolUseID,
   143→		Timestamp: time.Now().UTC(),
   144→		Data:      opts.IncrementalData,
   145→	}
   146→	cpData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
   147→	if err != nil {
   148→		return "", fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
   149→	}
   150→	cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
   151→	if err != nil {
   152→		return "", fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
   153→	}
   154→
   155→	cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
   156→	cpPath := taskPath + "checkpoints/" + cpFilename
   157→	entries[cpPath] = object.TreeEntry{
   158→		Name: cpPath,
   159→		Mode: filemode.Regular,
   160→		Hash: cpBlobHash,
   161→	}
   162→	return cpPath, nil
   163→}
