   165→// writeFinalTaskCheckpoint writes the final checkpoint.json and subagent transcript.
   166→func (s *GitStore) writeFinalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
   167→	checkpoint := taskCheckpointData{
   168→		SessionID:      opts.SessionID,
   169→		ToolUseID:      opts.ToolUseID,
   170→		CheckpointUUID: opts.CheckpointUUID,
   171→		AgentID:        opts.AgentID,
   172→	}
   173→	checkpointData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
   174→	if err != nil {
   175→		return "", fmt.Errorf("failed to marshal task checkpoint: %w", err)
   176→	}
   177→	blobHash, err := CreateBlobFromContent(s.repo, checkpointData)
   178→	if err != nil {
   179→		return "", fmt.Errorf("failed to create task checkpoint blob: %w", err)
   180→	}
   181→
   182→	checkpointFile := taskPath + "checkpoint.json"
   183→	entries[checkpointFile] = object.TreeEntry{
   184→		Name: checkpointFile,
   185→		Mode: filemode.Regular,
   186→		Hash: blobHash,
   187→	}
   188→
   189→	// Write subagent transcript if available
   190→	if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
   191→		agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath)
   192→		if readErr == nil {
   193→			agentBlobHash, agentBlobErr := CreateBlobFromContent(s.repo, agentContent)
   194→			if agentBlobErr == nil {
   195→				agentPath := taskPath + "agent-" + opts.AgentID + ".jsonl"
   196→				entries[agentPath] = object.TreeEntry{
   197→					Name: agentPath,
   198→					Mode: filemode.Regular,
   199→					Hash: agentBlobHash,
   200→				}
   201→			}
   202→		}
   203→	}
   204→
   205→	// Return task path without trailing slash
   206→	return taskPath[:len(taskPath)-1], nil
   207→}
