   209→// writeStandardCheckpointEntries writes transcript, prompts, context, metadata.json and any additional files.
   210→// If the checkpoint already exists (from a previous session), archives the existing files to a numbered subfolder.
   211→func (s *GitStore) writeStandardCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   212→	// Check if checkpoint already exists (multi-session support)
   213→	var existingMetadata *CommittedMetadata
   214→	metadataPath := basePath + paths.MetadataFileName
   215→	if entry, exists := entries[metadataPath]; exists {
   216→		// Read existing metadata to get session count
   217→		existing, err := s.readMetadataFromBlob(entry.Hash)
   218→		if err == nil {
   219→			existingMetadata = existing
   220→			// Archive existing session files to numbered subfolder
   221→			s.archiveExistingSession(basePath, existingMetadata, entries)
   222→		}
   223→	}
   224→
   225→	// Write transcript (from in-memory content or file path)
   226→	if err := s.writeTranscript(opts, basePath, entries); err != nil {
   227→		return err
   228→	}
   229→
   230→	// Write prompts
   231→	if len(opts.Prompts) > 0 {
   232→		promptContent := strings.Join(opts.Prompts, "\n\n---\n\n")
   233→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
   234→		if err != nil {
   235→			return err
   236→		}
   237→		entries[basePath+paths.PromptFileName] = object.TreeEntry{
   238→			Name: basePath + paths.PromptFileName,
   239→			Mode: filemode.Regular,
   240→			Hash: blobHash,
   241→		}
   242→	}
   243→
   244→	// Write context
   245→	if len(opts.Context) > 0 {
   246→		blobHash, err := CreateBlobFromContent(s.repo, opts.Context)
   247→		if err != nil {
   248→			return err
   249→		}
   250→		entries[basePath+paths.ContextFileName] = object.TreeEntry{
   251→			Name: basePath + paths.ContextFileName,
   252→			Mode: filemode.Regular,
   253→			Hash: blobHash,
   254→		}
   255→	}
   256→
   257→	// Copy additional metadata files from directory if specified
   258→	if opts.MetadataDir != "" {
   259→		if err := s.copyMetadataDir(opts.MetadataDir, basePath, entries); err != nil {
   260→			return fmt.Errorf("failed to copy metadata directory: %w", err)
   261→		}
   262→	}
   263→
   264→	// Write metadata.json (with merged info if existing metadata present)
   265→	return s.writeMetadataJSON(opts, basePath, entries, existingMetadata)
   266→}
