   268→// writeTranscript writes the transcript file from in-memory content or file path.
   269→// If the transcript exceeds MaxChunkSize, it's split into multiple chunk files.
   270→func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   271→	transcript := opts.Transcript
   272→	if len(transcript) == 0 && opts.TranscriptPath != "" {
   273→		var readErr error
   274→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
   275→		if readErr != nil {
   276→			// Non-fatal: transcript may not exist yet
   277→			transcript = nil
   278→		}
   279→	}
   280→	if len(transcript) == 0 {
   281→		return nil
   282→	}
   283→
   284→	// Chunk the transcript if it's too large
   285→	chunks, err := agent.ChunkTranscript(transcript, opts.Agent)
   286→	if err != nil {
   287→		return fmt.Errorf("failed to chunk transcript: %w", err)
   288→	}
   289→
   290→	// Write chunk files
   291→	for i, chunk := range chunks {
   292→		chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
   293→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
   294→		if err != nil {
   295→			return err
   296→		}
   297→		entries[chunkPath] = object.TreeEntry{
   298→			Name: chunkPath,
   299→			Mode: filemode.Regular,
   300→			Hash: blobHash,
   301→		}
   302→	}
   303→
   304→	// Content hash for deduplication (hash of full transcript)
   305→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
   306→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
   307→	if err != nil {
   308→		return err
   309→	}
   310→	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
   311→		Name: basePath + paths.ContentHashFileName,
   312→		Mode: filemode.Regular,
   313→		Hash: hashBlob,
   314→	}
   315→	return nil
   316→}
