   318→// writeMetadataJSON writes the metadata.json file for the checkpoint.
   319→// If existingMetadata is provided, merges session info from the previous session(s).
   320→func (s *GitStore) writeMetadataJSON(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingMetadata *CommittedMetadata) error {
   321→	metadata := CommittedMetadata{
   322→		CheckpointID:           opts.CheckpointID,
   323→		SessionID:              opts.SessionID,
   324→		Strategy:               opts.Strategy,
   325→		CreatedAt:              time.Now(),
   326→		Branch:                 opts.Branch,
   327→		CheckpointsCount:       opts.CheckpointsCount,
   328→		FilesTouched:           opts.FilesTouched,
   329→		Agent:                  opts.Agent,
   330→		IsTask:                 opts.IsTask,
   331→		ToolUseID:              opts.ToolUseID,
   332→		SessionCount:           1,
   333→		SessionIDs:             []string{opts.SessionID},
   334→		TranscriptUUIDAtStart:  opts.TranscriptUUIDAtStart,
   335→		TranscriptLinesAtStart: opts.TranscriptLinesAtStart,
   336→		TokenUsage:             opts.TokenUsage,
   337→	}
   338→
   339→	// Merge with existing metadata if present (multi-session checkpoint)
   340→	if existingMetadata != nil {
   341→		// Get existing session count (default to 1 for backwards compat)
   342→		existingCount := existingMetadata.SessionCount
   343→		if existingCount == 0 {
   344→			existingCount = 1
   345→		}
   346→		metadata.SessionCount = existingCount + 1
   347→
   348→		// Merge session IDs
   349→		existingIDs := existingMetadata.SessionIDs
   350→		if len(existingIDs) == 0 {
   351→			// Backwards compat: old metadata only had SessionID
   352→			existingIDs = []string{existingMetadata.SessionID}
   353→		}
   354→		metadata.SessionIDs = append(metadata.SessionIDs[:0], existingIDs...)
   355→		metadata.SessionIDs = append(metadata.SessionIDs, opts.SessionID)
   356→
   357→		// Merge files touched (deduplicated)
   358→		metadata.FilesTouched = mergeFilesTouched(existingMetadata.FilesTouched, opts.FilesTouched)
   359→
   360→		// Sum checkpoint counts
   361→		metadata.CheckpointsCount = existingMetadata.CheckpointsCount + opts.CheckpointsCount
   362→	}
   363→
   364→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(metadata, "", "  ")
   365→	if err != nil {
   366→		return fmt.Errorf("failed to marshal metadata: %w", err)
   367→	}
   368→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   369→	if err != nil {
   370→		return err
   371→	}
   372→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
   373→		Name: basePath + paths.MetadataFileName,
   374→		Mode: filemode.Regular,
   375→		Hash: metadataHash,
   376→	}
   377→	return nil
   378→}
   379→
   380→// mergeFilesTouched combines two file lists, removing duplicates.
   381→func mergeFilesTouched(existing, additional []string) []string {
   382→	seen := make(map[string]bool)
   383→	var result []string
   384→
   385→	for _, f := range existing {
   386→		if !seen[f] {
   387→			seen[f] = true
   388→			result = append(result, f)
   389→		}
   390→	}
   391→	for _, f := range additional {
   392→		if !seen[f] {
   393→			seen[f] = true
   394→			result = append(result, f)
   395→		}
   396→	}
   397→
   398→	sort.Strings(result)
   399→	return result
   400→}
