   402→// readMetadataFromBlob reads CommittedMetadata from a blob hash.
   403→func (s *GitStore) readMetadataFromBlob(hash plumbing.Hash) (*CommittedMetadata, error) {
   404→	blob, err := s.repo.BlobObject(hash)
   405→	if err != nil {
   406→		return nil, fmt.Errorf("failed to get blob: %w", err)
   407→	}
   408→
   409→	reader, err := blob.Reader()
   410→	if err != nil {
   411→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
   412→	}
   413→	defer reader.Close()
   414→
   415→	var metadata CommittedMetadata
   416→	if err := json.NewDecoder(reader).Decode(&metadata); err != nil {
   417→		return nil, fmt.Errorf("failed to decode metadata: %w", err)
   418→	}
   419→
   420→	return &metadata, nil
   421→}
