   423→// archiveExistingSession moves existing session files to a numbered subfolder.
   424→// The subfolder number is based on the current session count (so first archived session goes to "1/").
   425→func (s *GitStore) archiveExistingSession(basePath string, existingMetadata *CommittedMetadata, entries map[string]object.TreeEntry) {
   426→	// Determine archive folder number
   427→	sessionCount := existingMetadata.SessionCount
   428→	if sessionCount == 0 {
   429→		sessionCount = 1 // backwards compat
   430→	}
   431→	archivePath := fmt.Sprintf("%s%d/", basePath, sessionCount)
   432→
   433→	// Files to archive (standard checkpoint files at basePath, excluding tasks/ subfolder)
   434→	filesToArchive := []string{
   435→		paths.MetadataFileName,
   436→		paths.TranscriptFileName,
   437→		paths.PromptFileName,
   438→		paths.ContextFileName,
   439→		paths.ContentHashFileName,
   440→	}
   441→
   442→	// Move each file to archive folder
   443→	for _, filename := range filesToArchive {
   444→		srcPath := basePath + filename
   445→		if entry, exists := entries[srcPath]; exists {
   446→			// Add to archive location
   447→			dstPath := archivePath + filename
   448→			entries[dstPath] = object.TreeEntry{
   449→				Name: dstPath,
   450→				Mode: entry.Mode,
   451→				Hash: entry.Hash,
   452→			}
   453→			// Remove from original location (will be overwritten by new session)
   454→			delete(entries, srcPath)
   455→		}
   456→	}
   457→}
