   459→// readArchivedSessions reads transcript data from archived session subfolders (1/, 2/, etc.).
   460→// Returns sessions ordered by folder index (oldest first).
   461→func (s *GitStore) readArchivedSessions(checkpointTree *object.Tree, sessionCount int, agentType string) []ArchivedSession {
   462→	var archived []ArchivedSession
   463→
   464→	// Archived sessions are in numbered folders: 1/, 2/, etc.
   465→	// The most recent session is at the root level (not archived).
   466→	// Session count N means there are N-1 archived sessions.
   467→	for i := 1; i < sessionCount; i++ {
   468→		folderName := strconv.Itoa(i)
   469→
   470→		// Try to get the archived session subtree
   471→		subTree, err := checkpointTree.Tree(folderName)
   472→		if err != nil {
   473→			continue // Folder doesn't exist, skip
   474→		}
   475→
   476→		session := ArchivedSession{
   477→			FolderIndex: i,
   478→		}
   479→
   480→		// Read metadata to get session ID
   481→		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
   482→			if content, contentErr := metadataFile.Contents(); contentErr == nil {
   483→				var metadata CommittedMetadata
   484→				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
   485→					session.SessionID = metadata.SessionID
   486→				}
   487→			}
   488→		}
   489→
   490→		// Read transcript (handles both chunked and non-chunked formats)
   491→		if transcript, err := readTranscriptFromTree(subTree, agentType); err == nil && transcript != nil {
   492→			session.Transcript = transcript
   493→		}
   494→
   495→		// Read prompts
   496→		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
   497→			if content, contentErr := file.Contents(); contentErr == nil {
   498→				session.Prompts = content
   499→			}
   500→		}
   501→
   502→		// Only add if we got a transcript
   503→		if len(session.Transcript) > 0 {
   504→			archived = append(archived, session)
   505→		}
   506→	}
   507→
   508→	return archived
   509→}
