   511→// buildCommitMessage constructs the commit message with proper trailers.
   512→// The commit subject is always "Checkpoint: <id>" for consistency.
   513→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
   514→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
   515→	var commitMsg strings.Builder
   516→
   517→	// Subject line is always the checkpoint ID for consistent formatting
   518→	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))
   519→
   520→	// Include custom description in body if provided (e.g., task checkpoint details)
   521→	if opts.CommitSubject != "" {
   522→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
   523→	}
   524→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
   525→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
   526→	if opts.Agent != "" {
   527→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
   528→	}
   529→	if opts.EphemeralBranch != "" {
   530→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch))
   531→	}
   532→	if taskMetadataPath != "" {
   533→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.MetadataTaskTrailerKey, taskMetadataPath))
   534→	}
   535→
   536→	return commitMsg.String()
   537→}
