   557→// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
   558→// Returns nil, nil if the checkpoint doesn't exist.
   559→//
   560→
   561→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*ReadCommittedResult, error) {
   562→	_ = ctx // Reserved for future use
   563→
   564→	tree, err := s.getSessionsBranchTree()
   565→	if err != nil {
   566→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
   567→	}
   568→
   569→	checkpointPath := checkpointID.Path()
   570→	checkpointTree, err := tree.Tree(checkpointPath)
   571→	if err != nil {
   572→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
   573→	}
   574→
   575→	result := &ReadCommittedResult{}
   576→
   577→	// Read metadata.json
   578→	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   579→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
   580→			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
   581→			json.Unmarshal([]byte(content), &result.Metadata)
   582→			result.Metadata.Strategy = trailers.NormalizeStrategyName(result.Metadata.Strategy)
   583→		}
   584→	}
   585→
   586→	// Read transcript (handles both chunked and non-chunked formats)
   587→	if transcript, err := readTranscriptFromTree(checkpointTree, result.Metadata.Agent); err == nil && transcript != nil {
   588→		result.Transcript = transcript
   589→	}
   590→
   591→	// Read prompts
   592→	if file, fileErr := checkpointTree.File(paths.PromptFileName); fileErr == nil {
   593→		if content, contentErr := file.Contents(); contentErr == nil {
   594→			result.Prompts = content
   595→		}
   596→	}
   597→
   598→	// Read context
   599→	if file, fileErr := checkpointTree.File(paths.ContextFileName); fileErr == nil {
   600→		if content, contentErr := file.Contents(); contentErr == nil {
   601→			result.Context = content
   602→		}
   603→	}
   604→
   605→	// Read archived sessions if this is a multi-session checkpoint
   606→	if result.Metadata.SessionCount > 1 {
   607→		result.ArchivedSessions = s.readArchivedSessions(checkpointTree, result.Metadata.SessionCount, result.Metadata.Agent)
   608→	}
   609→
   610→	return result, nil
   611→}
