   613→// ListCommitted lists all committed checkpoints from the entire/sessions branch.
   614→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   615→//
   616→
   617→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   618→	_ = ctx // Reserved for future use
   619→
   620→	tree, err := s.getSessionsBranchTree()
   621→	if err != nil {
   622→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
   623→	}
   624→
   625→	var checkpoints []CommittedInfo
   626→
   627→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   628→	for _, bucketEntry := range tree.Entries {
   629→		if bucketEntry.Mode != filemode.Dir {
   630→			continue
   631→		}
   632→		// Bucket should be 2 hex chars
   633→		if len(bucketEntry.Name) != 2 {
   634→			continue
   635→		}
   636→
   637→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   638→		if treeErr != nil {
   639→			continue
   640→		}
   641→
   642→		// Each entry in the bucket is the remaining part of the checkpoint ID
   643→		for _, checkpointEntry := range bucketTree.Entries {
   644→			if checkpointEntry.Mode != filemode.Dir {
   645→				continue
   646→			}
   647→
   648→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   649→			if cpTreeErr != nil {
   650→				continue
   651→			}
   652→
   653→			// Reconstruct checkpoint ID: <bucket><remaining>
   654→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
   655→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
   656→			if cpIDErr != nil {
   657→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
   658→				continue
   659→			}
   660→
   661→			info := CommittedInfo{
   662→				CheckpointID: checkpointID,
   663→			}
   664→
   665→			// Get details from metadata file
   666→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   667→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   668→					var metadata CommittedMetadata
   669→					if err := json.Unmarshal([]byte(content), &metadata); err == nil {
   670→						info.SessionID = metadata.SessionID
   671→						info.CreatedAt = metadata.CreatedAt
   672→						info.CheckpointsCount = metadata.CheckpointsCount
   673→						info.FilesTouched = metadata.FilesTouched
   674→						info.Agent = metadata.Agent
   675→						info.IsTask = metadata.IsTask
   676→						info.ToolUseID = metadata.ToolUseID
   677→						info.SessionCount = metadata.SessionCount
   678→						info.SessionIDs = metadata.SessionIDs
   679→					}
   680→				}
   681→			}
   682→
   683→			checkpoints = append(checkpoints, info)
   684→		}
   685→	}
   686→
   687→	// Sort by time (most recent first)
   688→	sort.Slice(checkpoints, func(i, j int) bool {
   689→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   690→	})
   691→
   692→	return checkpoints, nil
   693→}
