   695→// GetTranscript retrieves the transcript for a specific checkpoint ID.
   696→func (s *GitStore) GetTranscript(ctx context.Context, checkpointID id.CheckpointID) ([]byte, error) {
   697→	result, err := s.ReadCommitted(ctx, checkpointID)
   698→	if err != nil {
   699→		return nil, err
   700→	}
   701→	if result == nil {
   702→		return nil, fmt.Errorf("checkpoint not found: %s", checkpointID)
   703→	}
   704→	if len(result.Transcript) == 0 {
   705→		return nil, fmt.Errorf("no transcript found for checkpoint: %s", checkpointID)
   706→	}
   707→	return result.Transcript, nil
   708→}
