   710→// GetSessionLog retrieves the session transcript and session ID for a checkpoint.
   711→// This is the primary method for looking up session logs by checkpoint ID.
   712→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   713→// Returns ErrNoTranscript if the checkpoint exists but has no transcript.
   714→func (s *GitStore) GetSessionLog(cpID id.CheckpointID) ([]byte, string, error) {
   715→	result, err := s.ReadCommitted(context.Background(), cpID)
   716→	if err != nil {
   717→		return nil, "", fmt.Errorf("failed to read checkpoint: %w", err)
   718→	}
   719→	if result == nil {
   720→		return nil, "", ErrCheckpointNotFound
   721→	}
   722→	if len(result.Transcript) == 0 {
   723→		return nil, "", ErrNoTranscript
   724→	}
   725→	return result.Transcript, result.Metadata.SessionID, nil
   726→}
