   728→// LookupSessionLog is a convenience function that opens the repository and retrieves
   729→// a session log by checkpoint ID. This is the primary entry point for callers that
   730→// don't already have a GitStore instance.
   731→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   732→// Returns ErrNoTranscript if the checkpoint exists but has no transcript.
   733→func LookupSessionLog(cpID id.CheckpointID) ([]byte, string, error) {
   734→	repo, err := git.PlainOpenWithOptions(".", &git.PlainOpenOptions{DetectDotGit: true})
