   742→// ensureSessionsBranch ensures the entire/sessions branch exists.
   743→func (s *GitStore) ensureSessionsBranch() error {
   744→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   745→	_, err := s.repo.Reference(refName, true)
   746→	if err == nil {
   747→		return nil // Branch exists
   748→	}
   749→
   750→	// Create orphan branch with empty tree
   751→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
   752→	if err != nil {
   753→		return err
   754→	}
   755→
   756→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
   757→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
   758→	if err != nil {
   759→		return err
   760→	}
   761→
   762→	newRef := plumbing.NewHashReference(refName, commitHash)
   763→	if err := s.repo.Storer.SetReference(newRef); err != nil {
   764→		return fmt.Errorf("failed to set branch reference: %w", err)
   765→	}
   766→	return nil
   767→}
