   769→// getSessionsBranchTree returns the tree object for the entire/sessions branch.
   770→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
   771→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   772→	ref, err := s.repo.Reference(refName, true)
   773→	if err != nil {
   774→		return nil, fmt.Errorf("sessions branch not found: %w", err)
   775→	}
   776→
   777→	commit, err := s.repo.CommitObject(ref.Hash())
   778→	if err != nil {
   779→		return nil, fmt.Errorf("failed to get commit object: %w", err)
   780→	}
   781→
   782→	tree, err := commit.Tree()
   783→	if err != nil {
   784→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
   785→	}
   786→
   787→	return tree, nil
   788→}
