   790→// CreateBlobFromContent creates a blob object from in-memory content.
   791→// Exported for use by strategy package (session_test.go)
   792→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
   793→	obj := repo.Storer.NewEncodedObject()
   794→	obj.SetType(plumbing.BlobObject)
   795→	obj.SetSize(int64(len(content)))
   796→
   797→	writer, err := obj.Writer()
   798→	if err != nil {
   799→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
   800→	}
   801→
   802→	_, err = writer.Write(content)
   803→	if err != nil {
   804→		_ = writer.Close()
   805→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
   806→	}
   807→	if err := writer.Close(); err != nil {
   808→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
   809→	}
   810→
   811→	hash, err := repo.Storer.SetEncodedObject(obj)
   812→	if err != nil {
   813→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
   814→	}
   815→	return hash, nil
   816→}
