   818→// copyMetadataDir copies all files from a directory to the checkpoint path.
   819→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
   820→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
   821→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
   822→		if err != nil {
   823→			return err
   824→		}
   825→		if info.IsDir() {
   826→			return nil
   827→		}
   828→
   829→		// Skip symlinks to prevent reading files outside the metadata directory.
   830→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
   831→		// then be captured in the checkpoint and stored in git history.
   832→		if info.Mode()&os.ModeSymlink != 0 {
   833→			return nil
   834→		}
   835→
   836→		// Get relative path within metadata dir
   837→		relPath, err := filepath.Rel(metadataDir, path)
   838→		if err != nil {
   839→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
   840→		}
   841→
   842→		// Prevent path traversal via symlinks pointing outside the metadata dir
   843→		if strings.HasPrefix(relPath, "..") {
   844→			return fmt.Errorf("path traversal detected: %s", relPath)
   845→		}
   846→
   847→		// Create blob from file
   848→		blobHash, mode, err := createBlobFromFile(s.repo, path)
   849→		if err != nil {
   850→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
   851→		}
   852→
   853→		// Store at checkpoint path
   854→		fullPath := basePath + relPath
   855→		entries[fullPath] = object.TreeEntry{
   856→			Name: fullPath,
   857→			Mode: mode,
   858→			Hash: blobHash,
   859→		}
   860→
   861→		return nil
   862→	})
   863→	if err != nil {
   864→		return fmt.Errorf("failed to walk metadata directory: %w", err)
   865→	}
   866→	return nil
   867→}
