   869→// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
   870→func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
   871→	// Get repository config (includes local settings)
   872→	cfg, err := repo.Config()
   873→	if err == nil {
   874→		name = cfg.User.Name
   875→		email = cfg.User.Email
   876→	}
   877→
   878→	// Provide sensible defaults if git user is not configured
   879→	if name == "" {
   880→		name = "Unknown"
   881→	}
   882→	if email == "" {
   883→		email = "unknown@local"
   884→	}
   885→
   886→	return name, email
   887→}
