   889→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
   890→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
   891→// The agentType is used for reassembling chunks in the correct format.
   892→func readTranscriptFromTree(tree *object.Tree, agentType string) ([]byte, error) {
   893→	// Collect all transcript-related files
   894→	var chunkFiles []string
   895→	var hasBaseFile bool
   896→
   897→	for _, entry := range tree.Entries {
   898→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
   899→			hasBaseFile = true
   900→		}
   901→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
   902→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
   903→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
   904→			if idx > 0 {
   905→				chunkFiles = append(chunkFiles, entry.Name)
   906→			}
   907→		}
   908→	}
   909→
   910→	// If we have chunk files, read and reassemble them
   911→	if len(chunkFiles) > 0 {
   912→		// Sort chunk files by index
   913→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
   914→
   915→		// Check if base file should be included as chunk 0
   916→		if hasBaseFile {
   917→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
   918→		}
   919→
   920→		var chunks [][]byte
   921→		for _, chunkFile := range chunkFiles {
   922→			file, err := tree.File(chunkFile)
   923→			if err != nil {
   924→				continue
   925→			}
   926→			content, err := file.Contents()
   927→			if err != nil {
   928→				continue
   929→			}
   930→			chunks = append(chunks, []byte(content))
   931→		}
   932→
   933→		if len(chunks) > 0 {
   934→			result, err := agent.ReassembleTranscript(chunks, agentType)
   935→			if err != nil {
   936→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
   937→			}
   938→			return result, nil
   939→		}
   940→	}
   941→
   942→	// Fall back to reading base file (non-chunked or backwards compatibility)
   943→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
   944→		if content, err := file.Contents(); err == nil {
   945→			return []byte(content), nil
   946→		}
   947→	}
   948→
   949→	// Try legacy filename
   950→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
   951→		if content, err := file.Contents(); err == nil {
   952→			return []byte(content), nil
   953→		}
   954→	}
   955→
   956→	return nil, nil
   957→}
