// DefaultAgentName is the default when none specified.
// This is a policy constant, not derived from an agent package to avoid circular imports.
const DefaultAgentName = "claude-code"

// GetByAgentType retrieves an agent by its type name.
// Accepts either human-readable type names (e.g., "Claude Code", "Gemini CLI") or
// registry names (e.g., "claude-code", "gemini").
func GetByAgentType(agentType string) (Agent, error) {
	// Try registry name first (direct lookup)
	if ag, err := Get(agentType); err == nil {
		return ag, nil
	}

	// Search by Type() for human-readable names
	registryMu.RLock()
	defer registryMu.RUnlock()

	for _, factory := range registry {
		ag := factory()
		if ag.Type() == agentType {
			return ag, nil
		}
	}

	return nil, fmt.Errorf("unknown agent type: %s", agentType)
}

