		isGeminiFormat := strings.Contains(agentType, "Gemini") || isGeminiJSONTranscript(fullTranscript)

		if isGeminiFormat {
			// Gemini uses JSON format with a "messages" array
			data.Transcript = []byte(fullTranscript)
