	sessionID := "test-claudecode-hook-session"
	sessionFile := filepath.Join(tmpDir, paths.CurrentSessionFile)
	if err := os.WriteFile(sessionFile, []byte(sessionID), 0o600); err != nil {
		t.Fatalf("failed to write session file: %v", err)
