	}
	if _, ok := entries[basePath+paths.TranscriptFileName+".001"]; ok {
		t.Error("original full.jsonl.001 should be removed from base path")
	}
	if _, ok := entries[basePath+paths.TranscriptFileName+".002"]; ok {
